/// `root_as_gct_unchecked`.
pub fn size_prefixed_root_as_gct_with_opts<'b, 'o>(
  opts: &'o ::flatbuffers::VerifierOptions,
  buf: &'b [u8],
) -> Result<GCT<'b>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::size_prefixed_root_with_opts::<GCT<'b>>(opts, buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a GCT and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `GCT`.
pub unsafe fn root_as_gct_unchecked(buf: &[u8]) -> GCT<'_> {
  unsafe { ::flatbuffers::root_unchecked::<GCT>(buf) }
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed GCT and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `GCT`.
pub unsafe fn size_prefixed_root_as_gct_unchecked(buf: &[u8]) -> GCT<'_> {
  unsafe { ::flatbuffers::size_prefixed_root_unchecked::<GCT>(buf) }
}
pub const GCT_IDENTIFIER: &str = "$GCT";

#[inline]
pub fn gct_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, GCT_IDENTIFIER, false)
}

#[inline]
pub fn gct_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, GCT_IDENTIFIER, true)
}

#[inline]
pub fn finish_gct_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<GCT<'a>>) {
  fbb.finish(root, Some(GCT_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_gct_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>, root: ::flatbuffers::WIPOffset<GCT<'a>>) {
  fbb.finish_size_prefixed(root, Some(GCT_IDENTIFIER));
}
